/*
 * ps1.h defines the fixed public interface of the CMSC 125 Problem Set 1 controller.
 *
 * Do not edit this file. It holds the limits, the exit codes, the shared
 * structures. It also holds the four module prototypes that the manual's Run
 * Contract defines. The reference solution compiles against this header unchanged.
 */
#ifndef PS1_H
#define PS1_H

#include <stdbool.h>
#include <stddef.h>
#include <stdio.h>
#include <stdint.h>
#include <sys/types.h>

/* Limits. A workload that breaks one is rejected before anything forks. */
#define PS1_MAX_WORKERS 16
#define PS1_MAX_NAME 15
#define PS1_MAX_TICKS 2048

/* One tick. The caller uses its result as the next seed. */
#define PS1_TICK_ITERATIONS 200000u

/*
 * One tick of work. The definition is fixed so that every worker burns the
 * same work for a tick. The loop cost limits how far the worker can progress
 * before SIGSTOP. The worker writes far less than one pipe buffer in that
 * interval. A caller uses the returned value as the next seed. This use stops
 * the compiler from removing the loop.
 */
static inline uint64_t ps1_tick(uint64_t seed)
{
    uint64_t value = seed;
    unsigned i;

    for (i = 0; i < PS1_TICK_ITERATIONS; i++) {
        value = value * 6364136223846793005ULL + 1442695040888963407ULL;
    }
    return value;
}

/* Seconds a worker may take to leave after SIGTERM before the SIGKILL. */
#define PS1_TERM_GRACE_MS 100

/* Exit codes. main maps a ps1_status onto one of these. */
#define PS1_EXIT_OK 0
#define PS1_EXIT_REJECTED 65
#define PS1_EXIT_FAULT 70
#define PS1_EXIT_INTERRUPTED 130

typedef enum {
    PS1_POLICY_FIFO = 0,
    PS1_POLICY_RR,
    PS1_POLICY_STCF
} ps1_policy;

typedef enum {
    PS1_OK = 0,           /* 0   every worker finished */
    PS1_ERR_REJECTED,     /* 65  the command line or the workload was refused */
    PS1_ERR_FAULT,        /* 70  a worker failed, or a system call did */
    PS1_ERR_INTERRUPTED   /* 130 SIGINT ended the run */
} ps1_status;

/* One line of a workload file: name, arrival tick, burst ticks, crash tick. */
typedef struct {
    char name[PS1_MAX_NAME + 1];
    long arrival;
    long burst;
    long crash; /* 0 runs to completion, else abort after this many ticks */
} ps1_worker;

typedef struct {
    ps1_worker workers[PS1_MAX_WORKERS];
    size_t count;
    long total_ticks;
} ps1_workload;

typedef struct {
    ps1_policy policy;
    long quantum;          /* ticks, 0 when the policy has no slice */
    const char *trace_dir; /* where the per-worker trace files are written */
    const char *path;      /* the workload path, for diagnostics */
} ps1_options;

/* A diagnostic message. main prints it to stderr and exits. */
typedef struct {
    char text[256];
} ps1_diag;

/* What one worker did, in ticks and in seconds on CLOCK_MONOTONIC. */
typedef struct {
    long arrival;
    long burst;
    long done;           /* ticks completed at the end of the run */
    long first_dispatch; /* tick of the first dispatch, -1 when never dispatched */
    long finish;         /* tick of completion, -1 when the worker did not finish */
    long dispatches;
    long preemptions;
    double arrival_time;        /* seconds */
    double first_dispatch_time; /* seconds, 0 when never dispatched */
    double finish_time;         /* seconds, 0 when the worker did not finish */
    bool finished;
} ps1_outcome;

/* Everything the report needs after the run. */
typedef struct {
    const ps1_workload *workload;
    const ps1_options *options;
    ps1_outcome outcomes[PS1_MAX_WORKERS];
    long ticks;          /* the work clock at the end of the run */
    bool interrupted;    /* SIGINT ended the run */
    bool faulted;        /* a worker failed before its burst was done */
    size_t fault_worker; /* the worker that failed */
} ps1_run;

/* ------------------------------------------------------------------ */
/* src/clock.c: the given monotonic clock. Do not edit.                */
/* ------------------------------------------------------------------ */

/* The seconds reading of CLOCK_MONOTONIC at the call. */
double ps1_now(void);

/* ------------------------------------------------------------------ */
/* src/workload.c: yours. Read and validate the workload file.         */
/* ------------------------------------------------------------------ */

/*
 * Loads the workload at path. On PS1_OK the caller may use *out: names are
 * unique, arrivals do not fall, and the arrival of every worker at or after
 * the second is no greater than the total burst of the workers before it.
 * On any other status, writes the stated message to *diag.
 */
ps1_status ps1_workload_load(const char *path, ps1_workload *out, ps1_diag *diag);

/* ------------------------------------------------------------------ */
/* src/trace.c: the given trace writer. Do not edit.                   */
/* ------------------------------------------------------------------ */

typedef struct ps1_trace ps1_trace; /* This type is opaque. Its definition is in trace.c. */

typedef enum {
    PS1_EVENT_DISPATCH = 0,
    PS1_EVENT_PREEMPT,
    PS1_EVENT_STOPPED,
    PS1_EVENT_COMPLETE
} ps1_event;

/*
 * Creates dir when it is missing and opens one trace file per worker, named
 * <name>.trace. A file stays empty until the controller records the worker's
 * arrival. On failure writes the stated message to *diag.
 */
ps1_trace *ps1_trace_open(const char *dir, const ps1_workload *wl, ps1_diag *diag);

/*
 * Writes the header of worker `index`, naming its arrival tick, its burst, and
 * the CLOCK_MONOTONIC second of its fork. Call it once, before the worker's
 * first event.
 */
ps1_status ps1_trace_arrival(ps1_trace *t, size_t index, double seconds);

/*
 * Appends one event to the trace of worker `index`: the event, the tick of
 * the work clock, the ticks that worker has completed, and the CLOCK_MONOTONIC
 * seconds of the call.
 */
ps1_status ps1_trace_event(ps1_trace *t, size_t index, ps1_event event,
                           long tick, long done, double seconds);

/* Flushes and closes every trace file. Accepts NULL. */
void ps1_trace_close(ps1_trace *t);

/* ------------------------------------------------------------------ */
/* src/worker.c: yours. The child side of the fork.                    */
/* ------------------------------------------------------------------ */

/*
 * Runs in the child forked by the controller. `index` is the worker's position
 * in the workload. The one descriptor is the worker's end of its progress
 * pipe, where it reports one byte per finished tick. This function never
 * returns: it leaves with exit status 0 when the burst is complete, or with
 * status 9 after a crash tick.
 */
void ps1_worker_main(const ps1_workload *wl, size_t index, int progress_fd);

/* ------------------------------------------------------------------ */
/* src/controller.c: yours. The scheduler.                             */
/* ------------------------------------------------------------------ */

/*
 * Forks the workers, decides who runs, preempts them, writes the traces,
 * reaps every child on every exit path, and fills *run. On a fault it writes
 * the stated message to *diag. On SIGINT it sets run->interrupted and returns
 * PS1_ERR_INTERRUPTED after the partial report is valid.
 */
ps1_status ps1_controller_run(const ps1_workload *wl, const ps1_options *opts,
                              ps1_run *run, ps1_diag *diag);

/* ------------------------------------------------------------------ */
/* src/report.c: yours. The metrics.                                   */
/* ------------------------------------------------------------------ */

/*
 * Writes the canonical report to out. The header line, then one line per
 * worker in workload order, then the average line.
 */
ps1_status ps1_report_print(const ps1_run *run, FILE *out);

#endif /* PS1_H */
